param([Parameter(Mandatory=$true)][string]$MameExecutable,[Parameter(Mandatory=$true)][string]$RomDirectory,[Parameter(Mandatory=$true)][string]$RunDirectory)
$ErrorActionPreference='Stop';$run=[IO.Path]::GetFullPath($RunDirectory);if(Test-Path $run){throw 'Use a fresh isolated directory'};New-Item -ItemType Directory $run|Out-Null
foreach($name in @('cfg','nvram','inp','snap','comments','state','diff')){New-Item -ItemType Directory "$run/$name"|Out-Null}
$commands=[Collections.Generic.List[string]]::new();$cases=[Collections.Generic.List[object]]::new();foreach($pc in @(0x280C,0x7CCF,0x43E9,0x44C3)){$commands.Add(('bpset {0:X}' -f $pc))}
$addresses=@(0x438E,0x4390,0x4392,0x4395,0x4398,0x439A,0x439E,0x439F,0x43A2,0x43A4,0x43A8,0x43AB,0x43AD,0x43AE,0x43AF,0x43B0,0x43B2,0x43B4,0x43B6,0x43BA,0x43BC,0x43BD,0x43BF,0x43C1,0x43C3,0x43C4,0x43C6,0x43C8,0x43CB,0x43CD,0x43CF,0x43D1,0x43D3,0x43D5,0x43D7,0x43D9,0x43DB,0x43DD,0x43DF,0x43E1,0x43E5,0x46D3,0x46D5,0x46D7,0x46D9,0x46DB,0x46DD,0x46E0,0x46E1,0x46E3,0x46E6,0x46E8,0x46EA,0x46EC,0x46EF,0x19B8,0x19BB,0x19BE,0x19C1,0x1A87,0x1A8A,0x1A8E,0x1A90,0x1A94,0x1A98,0x1A9A,0x1A9E,0x1AA2,0x1A05,0x1A08,0x1A0A,0x1A0C,0x1A0E,0x1A11,0x1A13,0x1A16,0x1A18,0x1A1A,0x1A1B,0x1A1E,0x1A20,0x1A23,0x1A26,0x1A28,0x1A2A,0x1A2D,0x1A30,0x1A33,0x1A58,0x1A5B,0x1A5D,0x1A5F,0x1A60,0x1A62,0x1A64,0x1A66,0x1A67,0x1A6A,0x1A6C,0x1A6E,0x1A71,0x1A73,0x1A76,0x1A79,0x1A7B,0x1A7D,0x1A80,0x1A83,0x1A86)
foreach($pc in $addresses){$commands.Add(('bpset {0:X},1,{{printf "PI id=%X pc=%04X cycle=%016X bytes=%02X%02X%02X%02X%02X\n",temp1,pc,totalcycles,b@pc,b@(pc+1),b@(pc+2),b@(pc+3),b@(pc+4);go}}' -f $pc))}
foreach($column in 0..7){foreach($variant in 0..7){
 $id=$cases.Count;$port5=if($variant -ge 5){8}else{($id*37) -band 7};$port6=if($variant -band 1){255}else{0};$port7=if($variant -band 2){255}else{0};$port2=if($variant -band 4){16}else{0};$aux=($id*53) -band 255;$prior=($id*13) -band 255;$sticky=($id*71) -band 255
 $state339=if($variant -in @(1,2,3,4)){1}else{0};$count88=@(0,0,8,9,255,0,0,0)[$variant];$state32f=if($variant -eq 7){255}else{0};$countE2=if($variant -eq 5){9}elseif($variant -eq 6){8}else{0}
 $cases.Add([ordered]@{id=$id;column=$column;port5=$port5;port6=$port6;port7=$port7;port2=$port2;aux=$aux;prior=$prior;sticky=$sticky;state339=$state339;count88=$count88;state32f=$state32f;countE2=$countE2})
 $commands.Add(('temp1=0x{0:X};pc=0x438c;cc=0x50;dp=0;s=0x700;w@700=0x280c;w@28=0x{1:X};w@c6=0x19b8;b@0x0=0xa5;b@0x1=0x3c;b@0x2=0x{2:X};b@0x3=0xa5;b@0x4=0xff;b@0x5=0x{3:X};b@0x6=0x{4:X};b@0x7=0x{5:X};b@89=0x{6:X};b@2a=0x{7:X};b@339=0x{8:X};b@88=0x{9:X};b@32f=0x{10:X};b@e2=0x{11:X};b@{12:X}=0x12;b@{13:X}=0x3c;b@c03=0;b@c02=0xff;b@c03=4;b@c02=0x{14:X}' -f $id,$column,$port2,$port5,$port6,$port7,$prior,$sticky,$state339,$count88,$state32f,$countE2,(0x8E+$column),(0x96+$column),$aux))
 $commands.Add('printf "PS id=%X pc=%04X cycle=%016X bytes=%02X%02X%02X%02X%02X\n",temp1,pc,totalcycles,b@pc,b@(pc+1),b@(pc+2),b@(pc+3),b@(pc+4)');$commands.Add('go')
 $commands.Add(('printf "PF id=%X cycle=%016X pc=%04X s=%04X prior=%02X sticky=%02X state339=%02X count88=%02X state32f=%02X counte2=%02X orlatch=%02X andlatch=%02X\n",temp1,totalcycles,pc,s,b@89,b@2a,b@339,b@88,b@32f,b@e2,b@{0:X},b@{1:X}' -f (0x8E+$column),(0x96+$column)))
}}
$commands.Add('quit');$commands|Set-Content "$run/debugger.cmd";$cases|ConvertTo-Json|Set-Content "$run/cases.json"
[ordered]@{classification='Synthetic original438C composed caller: inline46D3 branch or19B8/1A05/1A58, masked IRQ/FIRQ, injected RAM/PIA level, unpatched ROM flags. Stops before280C,7CCF,43E9 or44C3; not full coin validation/gameplay';mame_sha256=(Get-FileHash $MameExecutable).Hash}|ConvertTo-Json|Set-Content "$run/provenance.json"
$arguments=@('m4addr','-noreadconfig','-rompath',$RomDirectory,'-cfg_directory',"$run/cfg",'-nvram_directory',"$run/nvram",'-input_directory',"$run/inp",'-snapshot_directory',"$run/snap",'-comment_directory',"$run/comments",'-state_directory',"$run/state",'-diff_directory',"$run/diff",'-debug','-debugger','windows','-debugscript',"$run/debugger.cmd",'-debuglog','-video','none','-sound','none','-window','-skip_gameinfo','-nothrottle','-seconds_to_run','30');$arguments|ConvertTo-Json|Set-Content "$run/arguments.json"
Push-Location $run;try{& $MameExecutable @arguments *> console.txt;$code=$LASTEXITCODE;$code|Set-Content exit-code.txt}finally{Pop-Location};if($code -ne 0 -or (Select-String "$run/debug.log" -Pattern '^Error ' -Quiet)){throw 'Invalid panel continuation experiment'};Write-Output $run
